-- Habibi Bites Supabase Database Schema
-- Run this in the Supabase SQL Editor to set up your tables, seeds, and triggers.

-- Drop existing triggers and functions if they exist
DROP TRIGGER IF EXISTS trigger_check_order_capacity_and_delivery ON orders;
DROP FUNCTION IF EXISTS check_order_capacity_and_delivery();

-- Enable uuid extension
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 1. Create Settings table
CREATE TABLE IF NOT EXISTS settings (
  id INT PRIMARY KEY,
  delivery_charge_enabled BOOLEAN DEFAULT FALSE,
  delivery_charge_amount NUMERIC DEFAULT 150,
  max_active_orders INT DEFAULT 50,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. Create Menu Items table
CREATE TABLE IF NOT EXISTS menu_items (
  id TEXT PRIMARY KEY,
  category TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  prices JSONB NOT NULL,
  image TEXT DEFAULT '',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. Create Combo Deals table
CREATE TABLE IF NOT EXISTS deals (
  id BIGINT PRIMARY KEY,
  name TEXT NOT NULL,
  tag TEXT DEFAULT '',
  contents TEXT NOT NULL,
  price NUMERIC NOT NULL,
  category TEXT DEFAULT 'Deals',
  image TEXT DEFAULT '',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. Create Reviews table
CREATE TABLE IF NOT EXISTS reviews (
  id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
  name TEXT NOT NULL,
  rating INT CHECK (rating >= 1 AND rating <= 5),
  comment TEXT,
  date DATE DEFAULT CURRENT_DATE,
  approved BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 5. Create Orders table
CREATE TABLE IF NOT EXISTS orders (
  id TEXT PRIMARY KEY,
  customer JSONB NOT NULL,
  items JSONB NOT NULL,
  total NUMERIC NOT NULL,
  delivery_fee NUMERIC DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'received',
  payment TEXT DEFAULT 'Cash on Delivery',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updates JSONB DEFAULT '[]'::jsonb
);

