-- --- Row Level Security (RLS) Configuration ---

ALTER TABLE settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE menu_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE deals ENABLE ROW LEVEL SECURITY;
ALTER TABLE reviews ENABLE ROW LEVEL SECURITY;
ALTER TABLE orders ENABLE ROW LEVEL SECURITY;

-- 1. settings RLS Policies
CREATE POLICY "Allow public read for settings" ON settings FOR SELECT USING (true);
CREATE POLICY "Allow authenticated admin updates for settings" ON settings FOR UPDATE USING (auth.uid() IS NOT NULL);

-- 2. menu_items RLS Policies
CREATE POLICY "Allow public read for menu_items" ON menu_items FOR SELECT USING (true);
CREATE POLICY "Allow authenticated admin insert for menu_items" ON menu_items FOR INSERT WITH CHECK (auth.uid() IS NOT NULL);
CREATE POLICY "Allow authenticated admin update for menu_items" ON menu_items FOR UPDATE USING (auth.uid() IS NOT NULL);
CREATE POLICY "Allow authenticated admin delete for menu_items" ON menu_items FOR DELETE USING (auth.uid() IS NOT NULL);

-- 3. deals RLS Policies
CREATE POLICY "Allow public read for deals" ON deals FOR SELECT USING (true);
CREATE POLICY "Allow authenticated admin insert for deals" ON deals FOR INSERT WITH CHECK (auth.uid() IS NOT NULL);
CREATE POLICY "Allow authenticated admin update for deals" ON deals FOR UPDATE USING (auth.uid() IS NOT NULL);
CREATE POLICY "Allow authenticated admin delete for deals" ON deals FOR DELETE USING (auth.uid() IS NOT NULL);

-- 4. reviews RLS Policies
CREATE POLICY "Allow public read for approved reviews" ON reviews FOR SELECT USING (approved = true OR auth.uid() IS NOT NULL);
CREATE POLICY "Allow public insert for reviews" ON reviews FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow authenticated admin update/delete for reviews" ON reviews FOR ALL USING (auth.uid() IS NOT NULL);

-- 5. orders RLS Policies
CREATE POLICY "Allow public read for orders by id or phone" ON orders FOR SELECT USING (true); -- We do filtering in JS
CREATE POLICY "Allow public insert for orders" ON orders FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow authenticated admin updates for orders" ON orders FOR ALL USING (auth.uid() IS NOT NULL);

-- --- Server-Side PL/pgSQL Order capacity and pricing safety Trigger ---

CREATE OR REPLACE FUNCTION check_order_capacity_and_delivery()
RETURNS TRIGGER AS $$
DECLARE
  active_count INTEGER;
  settings_rec RECORD;
  calculated_delivery_fee NUMERIC := 0;
  item_elem JSONB;
  subtotal NUMERIC := 0;
BEGIN
  -- 1. Read settings record (id = 1)
  SELECT * INTO settings_rec FROM settings WHERE id = 1;
  IF NOT FOUND THEN
    settings_rec.max_active_orders := 50;
    settings_rec.delivery_charge_enabled := FALSE;
    settings_rec.delivery_charge_amount := 150;
  END IF;

  -- 2. Check Active Orders Capacity Limit
  SELECT COUNT(*) INTO active_count 
  FROM orders 
  WHERE status IN ('received', 'queue', 'cooking', 'packing', 'delivery');

  IF active_count >= settings_rec.max_active_orders THEN
    RAISE EXCEPTION 'We are at full capacity right now, please try again shortly'
      USING ERRCODE = 'P0001';
  END IF;

  -- 3. Calculate and Force Delivery Fee
  IF settings_rec.delivery_charge_enabled THEN
    calculated_delivery_fee := settings_rec.delivery_charge_amount;
  ELSE
    calculated_delivery_fee := 0;
  END IF;

  NEW.delivery_fee := calculated_delivery_fee;

  -- 4. Re-calculate total price to ensure it matches
  FOR item_elem IN SELECT * FROM jsonb_array_elements(NEW.items) LOOP
    subtotal := subtotal + ((item_elem->>'price')::numeric * (item_elem->>'quantity')::numeric);
  END LOOP;
  NEW.total := subtotal + NEW.delivery_fee;

  -- Force initial status to 'received' and insert start update time
  NEW.status := 'received';
  NEW.updates := jsonb_build_array(jsonb_build_object('stage', 'received', 'time', to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SSOF')));
  
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trigger_check_order_capacity_and_delivery
BEFORE INSERT ON orders
FOR EACH ROW
EXECUTE FUNCTION check_order_capacity_and_delivery();
